protocol Greeter { func hello() -> String }
extension Greeter {
    func hello() -> String { "default" }
    func bye() -> String { "bye default" }      // NOT a requirement
}
struct Custom: Greeter {
    func hello() -> String { "custom" }
    func bye() -> String { "bye custom" }
}
let g: any Greeter = Custom()
g.hello()   // "custom"       witness table
g.bye()     // "bye default"  static dispatch
